package com.ptms.service;import com.ptms.domain.*;import com.ptms.repository.*;import com.ptms.exception.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.nio.charset.StandardCharsets;import java.security.*;import java.time.*;import java.util.*;@Service @Transactional public class AuthService{private final AppUserRepository r;public AuthService(AppUserRepository r){this.r=r;}public Map<String,Object> login(String username,String password){AppUser u=r.findByUsernameIgnoreCase(username).orElseThrow(()->new BusinessRuleException("Invalid username or password"));if(!u.isEnabled()||!hash(password).equals(u.getPasswordHash()))throw new BusinessRuleException("Invalid username or password");if(u.getRole()==UserRole.SUPER_USER&&u.isMustChangePassword()&&!hash("admin").equals(u.getPasswordHash())){u.setMustChangePassword(false);r.save(u);}return view(u);}public List<Map<String,Object>> users(){return r.findAll().stream().sorted(Comparator.comparing(AppUser::getId)).map(this::view).toList();}public Map<String,Object> save(Long id,Map<String,Object> q){AppUser u=id==null?new AppUser():r.findById(id).orElseThrow(()->new ResourceNotFoundException("User not found"));String fullName=text(q.get("fullName"));String username=text(q.get("username"));String email=text(q.get("email"));if(fullName.isBlank())throw new BusinessRuleException("Full name is required");if(username.isBlank())throw new BusinessRuleException("Username is required");if(email.isBlank())throw new BusinessRuleException("Email is required");r.findByUsernameIgnoreCase(username).filter(x->id==null||!x.getId().equals(id)).ifPresent(x->{throw new BusinessRuleException("Username already exists");});r.findByEmailIgnoreCase(email).filter(x->id==null||!x.getId().equals(id)).ifPresent(x->{throw new BusinessRuleException("Email already exists");});u.setFullName(fullName);u.setUsername(username);u.setEmail(email);try{u.setRole(UserRole.valueOf(text(q.get("role"))));}catch(Exception e){throw new BusinessRuleException("Select a valid user role");}u.setEnabled(!Boolean.FALSE.equals(q.get("enabled")));Object p=q.get("password");if(p!=null&&!String.valueOf(p).isBlank()){u.setPasswordHash(hash(String.valueOf(p)));u.setMustChangePassword(id==null);}if(id==null&&u.getPasswordHash()==null)throw new BusinessRuleException("Password is required");Object image=q.get("profileImage");if(image!=null){String imageValue=String.valueOf(image);if(!imageValue.isBlank()&&!imageValue.startsWith("data:image/"))throw new BusinessRuleException("Profile picture must be an image");if(imageValue.length()>2_000_000)throw new BusinessRuleException("Profile picture is too large");u.setProfileImage(imageValue.isBlank()?null:imageValue);}return view(r.saveAndFlush(u));}public void delete(Long id){AppUser u=r.findById(id).orElseThrow();if(u.getRole()==UserRole.SUPER_USER)throw new BusinessRuleException("Super User cannot be deleted");r.delete(u);}public String forgot(String email){AppUser u=r.findByEmailIgnoreCase(email).orElse(null);if(u!=null){u.setResetToken(UUID.randomUUID().toString());u.setResetTokenExpiresAt(LocalDateTime.now().plusMinutes(30));r.save(u);}return "If the email exists, reset instructions have been created.";}public void reset(String token,String password){AppUser u=r.findByResetToken(token).orElseThrow(()->new BusinessRuleException("Invalid reset token"));if(u.getResetTokenExpiresAt()==null||u.getResetTokenExpiresAt().isBefore(LocalDateTime.now()))throw new BusinessRuleException("Reset token expired");u.setPasswordHash(hash(password));u.setResetToken(null);u.setResetTokenExpiresAt(null);u.setMustChangePassword(false);r.save(u);}public void change(String username,String oldPassword,String newPassword){AppUser u=r.findByUsernameIgnoreCase(username).orElseThrow();if(!hash(oldPassword).equals(u.getPasswordHash()))throw new BusinessRuleException("Current password is incorrect");u.setPasswordHash(hash(newPassword));u.setMustChangePassword(false);r.save(u);}public void ensureAdmin(){if(r.findByUsernameIgnoreCase("admin").isEmpty()){AppUser u=new AppUser();u.setFullName("PTMS Super User");u.setUsername("admin");u.setEmail("admin@ptms.local");u.setRole(UserRole.SUPER_USER);u.setEnabled(true);u.setMustChangePassword(true);u.setPasswordHash(hash("admin"));r.save(u);}}private Map<String,Object> view(AppUser u){Map<String,Object>m=new LinkedHashMap<>();m.put("id",u.getId());m.put("fullName",u.getFullName());m.put("username",u.getUsername());m.put("email",u.getEmail());m.put("role",u.getRole());m.put("enabled",u.isEnabled());boolean mustChange=u.getRole()==UserRole.SUPER_USER?hash("admin").equals(u.getPasswordHash()):u.isMustChangePassword();m.put("mustChangePassword",mustChange);m.put("profileImage",u.getProfileImage());return m;}private String text(Object v){return v==null?"":String.valueOf(v).trim();}private String hash(String s){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}}
